script:
(function () {
  'use strict';
  // Holding period return (HPR), two ways.
  // 1) From values: HPR = (ending value - beginning value + income) / beginning value;
  //    price return = (end - begin) / begin; income return = income / begin;
  //    annualized = (1 + HPR)^(1 / years) - 1, years = days / 365, months / 12 or years.
  // 2) Linked sub-period returns: HPR = (1 + r_1)(1 + r_2)...(1 + r_n) - 1;
  //    annualized = (1 + HPR)^(periods per year / n) - 1; geometric average per period =
  //    (1 + HPR)^(1 / n) - 1.
  // Checked in Node (hpr.test.js): $10,000 -> $11,200 with $300 income = 15% (12% price + 3% income);
  // over 18 months -> 9.7653% a year (1.15^(1/1.5)); $100 -> $90 with $2 over 1 year = -8%;
  // 365 days = exactly 1 year; quarters 3%, -1.5%, 4.2%, 2% -> 7.8304% (1.03 x 0.985 x 1.042 x 1.02
  // = 1.078304), which is also the annualized figure for four quarters; months 1% x 12 -> 12.6825%;
  // two yearly returns 10% and -10% -> -1% total, -0.5013% a year; a -100% period -> -100%.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MAX_PERIODS = 60;
  var UNIT_YEARS = { days: 1 / 365, months: 1 / 12, years: 1 };
  var PERIOD_NAMES = { 12: 'Month', 4: 'Quarter', 2: 'Half year', 1: 'Year' };
  var OUT1 = ['hpHpr', 'hpAnnual', 'hpGain', 'hpPriceGain', 'hpPriceRet', 'hpIncomeRet', 'hpYears'];
  var OUT2 = ['hpChainHpr', 'hpChainAnnual', 'hpChainEnd', 'hpChainCount', 'hpChainGeo', 'hpChainSum'];
  var INPUT_CLASS = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';

  // --- calc start
  function annualize(growth, years) {
    if (growth <= 0) return -1;
    return Math.pow(growth, 1 / years) - 1;
  }

  function hprFromValues(begin, end, income, years) {
    var hpr = (end - begin + income) / begin;
    return {
      hpr: hpr, gain: end - begin + income, priceGain: end - begin,
      priceRet: (end - begin) / begin, incomeRet: income / begin,
      annual: years > 0 ? annualize(1 + hpr, years) : NaN
    };
  }

  function linkReturns(rets, perYear) {
    var growth = 1, sum = 0, rows = [];
    for (var i = 0; i < rets.length; i++) {
      growth *= 1 + rets[i];
      sum += rets[i];
      rows.push({ ret: rets[i], toDate: growth - 1, growth: growth });
    }
    var n = rets.length;
    return {
      hpr: growth - 1, growth: growth, sum: sum, rows: rows,
      geo: annualize(growth, n), annual: annualize(growth, n / perYear)
    };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function fix(x, dp) {
    if (Math.abs(x) < 0.5 * Math.pow(10, -dp)) x = 0;
    return x.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }).replace(/^-/, '−');
  }
  function pct(x) {
    if (!isFinite(x) || x > 1e6) return 'Over 100,000,000%';
    return fix(x * 100, 2) + '%';
  }
  function usd(x) { return money.format(Math.abs(x) < 0.005 ? 0 : x).replace(/^-/, '−'); }
  function fail(errId, outputs, msg) {
    var error = el(errId);
    error.hidden = !msg;
    error.textContent = msg;
    outputs.forEach(function (id) { el(id).textContent = '–'; });
  }

  // ----- From values -----
  function updateValues() {
    var begin = parseFloat(el('hpBegin').value), end = parseFloat(el('hpEnd').value),
        incomeTxt = el('hpIncome').value.trim(), income = incomeTxt === '' ? 0 : parseFloat(incomeTxt),
        length = parseFloat(el('hpLength').value), unit = el('hpUnit').value;
    var perUnit = UNIT_YEARS[unit] || UNIT_YEARS.months;
    var msg = '';
    if (!isFinite(begin) || begin <= 0 || begin > 1e12) msg = 'Enter a beginning value above $0.';
    else if (!isFinite(end) || end < 0 || end > 1e12) msg = 'Enter an ending value of $0 or more.';
    else if (!isFinite(income) || income < 0 || income > 1e12) msg = 'Enter income of $0 or more.';
    else if (!isFinite(length) || length <= 0 || length * perUnit > 100) msg = 'Enter a holding period above 0 and up to 100 years.';
    var note = el('hpNote');
    if (msg) { fail('hpError', OUT1, msg); note.hidden = true; return; }
    fail('hpError', OUT1, '');

    var years = length * perUnit;
    var r = hprFromValues(begin, end, income, years);
    el('hpHpr').textContent = pct(r.hpr);
    el('hpAnnual').textContent = pct(r.annual);
    el('hpGain').textContent = usd(r.gain);
    el('hpPriceGain').textContent = usd(r.priceGain);
    el('hpPriceRet').textContent = pct(r.priceRet);
    el('hpIncomeRet').textContent = pct(r.incomeRet);
    el('hpYears').textContent = fix(years, 3);
    if (years < 1) {
      note.hidden = false;
      note.textContent = 'This holding period is shorter than a year, so the annualized figure assumes the same return repeats for a full year. Treat it with care: short periods can annualize to very large or very small numbers.';
    } else {
      note.hidden = true;
    }
  }

  // ----- Linked periods -----
  function retInputs() { return Array.prototype.slice.call(document.querySelectorAll('#hpRows input')); }

  function periodName() { return PERIOD_NAMES[el('hpPeriod').value] || 'Period'; }

  function relabel() {
    var name = periodName();
    retInputs().forEach(function (input, k) {
      var label = el('hpLbl' + (k + 1));
      if (label) label.textContent = name + ' ' + (k + 1);
    });
  }

  function syncButtons() {
    var n = retInputs().length;
    el('hpAdd').disabled = n >= MAX_PERIODS;
    el('hpRemove').disabled = n <= 1;
  }

  function addPeriod() {
    var n = retInputs().length + 1;
    if (n > MAX_PERIODS) return;
    var wrap = document.createElement('div');
    wrap.className = 'flex items-center gap-3';
    var label = document.createElement('label');
    label.id = 'hpLbl' + n;
    label.className = 'w-24 shrink-0 text-sm text-ink-muted';
    label.htmlFor = 'hpRet' + n;
    label.textContent = periodName() + ' ' + n;
    var group = document.createElement('div');
    group.className = 'input-group flex-1';
    var input = document.createElement('input');
    input.type = 'number';
    input.id = 'hpRet' + n;
    input.className = INPUT_CLASS;
    input.min = '-100';
    input.step = '0.1';
    input.setAttribute('inputmode', 'decimal');
    var affix = document.createElement('span');
    affix.className = 'input-affix';
    affix.textContent = '%';
    group.appendChild(input);
    group.appendChild(affix);
    wrap.appendChild(label);
    wrap.appendChild(group);
    el('hpRows').appendChild(wrap);
    syncButtons();
    updateChain();
    input.focus();
  }

  function removePeriod() {
    var rows = el('hpRows');
    if (retInputs().length <= 1) return;
    rows.removeChild(rows.lastElementChild);
    syncButtons();
    updateChain();
  }

  function updateChain() {
    relabel();
    var perYear = parseInt(el('hpPeriod').value, 10);
    if (!PERIOD_NAMES[perYear]) perYear = 4;
    var startTxt = el('hpStart').value.trim(), start = startTxt === '' ? 0 : parseFloat(startTxt);
    var rets = [], labels = [], msg = '';
    retInputs().forEach(function (input, k) {
      if (msg || input.value.trim() === '') return;
      var v = parseFloat(input.value);
      if (!isFinite(v) || v < -100 || v > 10000) msg = 'Each return must be a percentage from -100% to 10,000%.';
      else { rets.push(v / 100); labels.push(k + 1); }
    });
    if (!msg && (!isFinite(start) || start < 0 || start > 1e12)) msg = 'Enter a starting amount from $0 to $1 trillion.';
    if (!msg && !rets.length) msg = 'Enter at least one period return.';
    if (msg) { fail('hpChainError', OUT2, msg); el('hpChainTable').innerHTML = ''; return; }
    fail('hpChainError', OUT2, '');

    var r = linkReturns(rets, perYear);
    var name = periodName();
    el('hpChainHpr').textContent = pct(r.hpr);
    el('hpChainAnnual').textContent = pct(r.annual);
    el('hpChainEnd').textContent = start > 0 ? usd(start * r.growth) : '–';
    el('hpChainCount').textContent = rets.length + ' (' + fix(rets.length / perYear, 2) + ' years)';
    el('hpChainGeo').textContent = pct(r.geo);
    el('hpChainSum').textContent = pct(r.sum);
    el('hpChainTable').innerHTML = r.rows.map(function (row, k) {
      return '<tr><td>' + name + ' ' + labels[k] + '</td><td>' + pct(row.ret) + '</td><td>' + pct(row.toDate) +
             '</td><td>' + (start > 0 ? usd(start * row.growth) : '–') + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('hpForm');
    form.addEventListener('input', updateValues);
    form.addEventListener('change', updateValues);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    var chain = el('hpChainForm');
    chain.addEventListener('input', updateChain);
    chain.addEventListener('change', updateChain);
    chain.addEventListener('submit', function (e) { e.preventDefault(); });
    el('hpAdd').addEventListener('click', addPeriod);
    el('hpRemove').addEventListener('click', removePeriod);
    syncButtons();
    updateValues();
    updateChain();
  });
})();
